from math import isqrt


def predict(start, steps):
    cells = {int(p): s for p, s in start.items() if s != '.'}
    if steps <= 0 or not cells:
        return cells

    RULE = {
        ('.', 'a', 'b'): '.', ('a', 'b', '.'): 'b', ('b', '.', '.'): 'a',
        ('.', 'b', 'a'): '.', ('b', 'a', '.'): 'a', ('a', '.', '.'): 'b',
        ('.', '.', 'c'): 'c', ('.', 'd', '.'): 'd', ('a', '.', 'c'): 'd',
        ('a', '.', 'd'): 'b', ('b', '.', 'd'): 'a', ('.', 'b', 'd'): 'c',
        ('b', 'd', '.'): 'e', ('.', 'a', 'd'): 'c', ('a', 'd', '.'): 'e',
        ('e', '.', '.'): 'd', ('d', '.', 'c'): 'c', ('.', 'd', 'c'): 'd',
        ('d', 'c', '.'): 'a', ('.', 'd', 'a'): 'd',
    }

    def step(c):
        cand = set()
        for p in c:
            cand.add(p - 1)
            cand.add(p)
            cand.add(p + 1)
        out = {}
        get = c.get
        rg = RULE.get
        for p in cand:
            s = rg((get(p - 1, '.'), get(p, '.'), get(p + 1, '.')), '.')
            if s != '.':
                out[p] = s
        return out

    def split(c):
        if not c:
            return []
        ps = sorted(c)
        out, cur = [], [ps[0]]
        for p in ps[1:]:
            if p - cur[-1] > 2:
                out.append(cur)
                cur = [p]
            else:
                cur.append(p)
        out.append(cur)
        return out

    def stable_info(c):
        out = []
        for ps in split(c):
            n = len(ps)
            if n == 1:
                p = ps[0]
                s = c[p]
                if s == 'a' or s == 'b':
                    out.append(('r1', p, p, 1, s))
                elif s == 'c':
                    out.append(('c', p, p, -1, 'c'))
                elif s == 'd':
                    out.append(('d', p, p, 0, 'd'))
                else:
                    return None
            elif n == 2 and ps[1] == ps[0] + 1:
                a = c[ps[0]] + c[ps[1]]
                if a == 'ab' or a == 'ba':
                    out.append(('r2', ps[0], ps[1], 1, a))
                else:
                    return None
            else:
                return None
        return out

    def add_cluster(out, info, n):
        k, lo, _, _, s = info
        if k == 'r1':
            out[lo + n] = s if n % 2 == 0 else ('a' if s == 'b' else 'b')
        elif k == 'r2':
            if n % 2 == 0:
                out[lo + n] = s[0]
                out[lo + n + 1] = s[1]
            else:
                out[lo + n] = s[1]
                out[lo + n + 1] = s[0]
        elif k == 'c':
            out[lo - n] = 'c'
        else:
            out[lo] = 'd'

    def advance(c, n):
        if n == 0 or not c:
            return dict(c)
        info = stable_info(c)
        out = {}
        for item in info:
            add_cluster(out, item, n)
        return out

    def shuttle_standard(L, R, t):
        # estado estándar: d en L, c en R-3, d en R
        if t:
            b = 2 * (R - L) - 4
            n = (isqrt(b * b + 4 * t) - b) // 2
            s = n * (n + b)
            if s > t:
                n -= 1
                s = n * (n + b)
            t -= s
            R += n
        a = R - L - 4
        if t <= a:
            return {L: 'd', R - 3 - t: 'c', R: 'd'}
        if t == 2 * (R - L) - 4:
            return {L: 'd', R - 1: 'c', R: 'e'}
        u = t - a - 1
        return {L: 'd', L + 1 + u: ('a' if u % 2 == 0 else 'b'), R: 'd'}

    def shuttle(L, mid, R, t):
        k, x, _, _, s = mid
        if k == 'c':
            a = x - L - 1
            d0 = x + R - 2 * L
            if t <= a:
                return {L: 'd', x - t: 'c', R: 'd'}
            if t == d0 - 1:
                return {L: 'd', R - 1: 'c', R: 'e'}
            if t < d0:
                u = t - a - 1
                return {L: 'd', L + 1 + u: ('a' if u % 2 == 0 else 'b'), R: 'd'}
            return shuttle_standard(L, R + 1, t - d0)
        d0 = R - x + 1
        if t == d0 - 1:
            return {L: 'd', R - 1: 'c', R: 'e'}
        if t < d0:
            return {L: 'd', x + t: (s if t % 2 == 0 else ('a' if s == 'b' else 'b')), R: 'd'}
        return shuttle_standard(L, R + 1, t - d0)

    while steps and cells:
        info = stable_info(cells)
        if info is not None:
            m = len(info)
            if m >= 3 and info[-3][0] == 'd' and info[-2][0] in ('c', 'r1') and info[-1][0] == 'd':
                ok = True
                for item in info[:-3]:
                    if item[3] > 0:
                        ok = False
                        break
                if ok:
                    out = {}
                    for item in info[:-3]:
                        add_cluster(out, item, steps)
                    out.update(shuttle(info[-3][1], info[-2], info[-1][1], steps))
                    return out
            nxt = None
            for i in range(m - 1):
                hi1, v1 = info[i][2], info[i][3]
                lo2, v2 = info[i + 1][1], info[i + 1][3]
                g = lo2 - hi1 - 1
                if g <= 2:
                    nxt = 0
                    break
                r = v1 - v2
                if r > 0:
                    t = (g - 2 + r - 1) // r
                    if nxt is None or t < nxt:
                        nxt = t
            if nxt is None or nxt > steps:
                return advance(cells, steps)
            if nxt:
                cells = advance(cells, nxt)
                steps -= nxt
                continue
        cells = step(cells)
        steps -= 1
    return cells

