            return []
        ps = sorted(c)
        out = []
        cur = [ps[0]]
        for p in ps[1:]:
            if p - cur[-1] > 2:
                out.append({q: c[q] for q in cur})
                cur = [p]
            else:
                cur.append(p)
        out.append({q: c[q] for q in cur})
        return out

    def kind(g):
        ps = sorted(g)
        if len(ps) == 1:
            p = ps[0]
            s = g[p]
            if s == 'a' or s == 'b':
                return ('r1', p, s)
            if s == 'c':
                return ('c', p)
            if s == 'd':
                return ('d', p)
            return None
        if len(ps) == 2 and ps[1] == ps[0] + 1:
            a = g[ps[0]] + g[ps[1]]
            if a == 'ab' or a == 'ba':
                return ('r2', ps[0], a)
        return None

    def stable_info(c):
        gs = split(c)
        info = []
        for g in gs:
            k = kind(g)
            if k is None:
                return None
            if k[0] == 'r1':
                info.append((k[0], k[1], k[1], 1, k[2]))
            elif k[0] == 'r2':
                info.append((k[0], k[1], k[1] + 1, 1, k[2]))
            elif k[0] == 'c':
                info.append((k[0], k[1], k[1], -1, 'c'))
            else:
                info.append((k[0], k[1], k[1], 0, 'd'))
        return info

    def advance(c, n):
        if n == 0 or not c:
            return dict(c)
        out = {}
        for g in split(c):
            k = kind(g)
            if k[0] == 'r1':
                p, s = k[1], k[2]
                out[p + n] = s if n % 2 == 0 else ('a' if s == 'b' else 'b')
            elif k[0] == 'r2':
                p, a = k[1], k[2]
                if n % 2 == 0:
                    out[p + n] = a[0]
                    out[p + n + 1] = a[1]
                else:
                    out[p + n] = a[1]
                    out[p + n + 1] = a[0]
            elif k[0] == 'c':
                out[k[1] - n] = 'c'
            else:
                out[k[1]] = 'd'
        return out

    RULE = {
        ('.', 'a', 'b'): '.', ('a', 'b', '.'): 'b', ('b', '.', '.'): 'a',
        ('.', 'b', 'a'): '.', ('b', 'a', '.'): 'a', ('a', '.', '.'): 'b',
        ('.', '.', 'c'): 'c', ('.', 'd', '.'): 'd', ('a', '.', 'c'): 'd',
        ('a', '.', 'd'): 'b', ('b', '.', 'd'): 'a', ('.', 'b', 'd'): 'c',
        ('b', 'd', '.'): 'e', ('.', 'a', 'd'): 'c', ('a', 'd', '.'): 'e',
        ('e', '.', '.'): 'd', ('d', '.', 'c'): 'c', ('.', 'd', 'c'): 'd',
        ('d', 'c', '.'): 'a', ('.', 'd', 'a'): 'd',
    }

    def step(c):
        cand = set()
        for p in c:
            cand.add(p - 1)
            cand.add(p)
            cand.add(p + 1)
        out = {}
        get = c.get
        rg = RULE.get
        for p in cand:
            s = rg((get(p - 1, '.'), get(p, '.'), get(p + 1, '.')), '.')
            if s != '.':
                out[p] = s
        return out

    while steps and cells:
        info = stable_info(cells)
        if info is not None:
            good = True
            nxt = None
            for i in range(len(info) - 1):
                _, _, hi1, v1, _ = info[i]
                _, lo2, _, v2, _ = info[i + 1]
                g = lo2 - hi1 - 1
                if g <= 2:
                    good = False
                    break
                r = v1 - v2
                if r > 0:
                    t = (g - 2 + r - 1) // r
                    if nxt is None or t < nxt:
                        nxt = t
            if good:
                if nxt is None or nxt > steps:
                    return advance(cells, steps)
                cells = advance(cells, nxt)
                steps -= nxt
                continue
        cells = step(cells)
        steps -= 1
    return cells
